create extension if not exists pgcrypto;
create type public.user_role as enum ('teacher','student');
create type public.invitation_status as enum ('pending','accepted','revoked','expired');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,email text not null unique,role public.user_role not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.teachers(id uuid primary key default gen_random_uuid(),profile_id uuid not null unique references public.profiles(id) on delete cascade,created_at timestamptz not null default now());
create table public.students(id uuid primary key default gen_random_uuid(),profile_id uuid not null unique references public.profiles(id) on delete cascade,teacher_id uuid not null references public.teachers(id) on delete cascade,created_at timestamptz not null default now());
create table public.invitations(id uuid primary key default gen_random_uuid(),teacher_id uuid not null references public.teachers(id) on delete cascade,student_email text not null,token uuid not null unique default gen_random_uuid(),status public.invitation_status not null default 'pending',created_at timestamptz not null default now(),expires_at timestamptz not null);
create unique index one_pending_invite_per_teacher_email on public.invitations(teacher_id,lower(student_email)) where status='pending';
create index invitations_token_idx on public.invitations(token);create index students_teacher_idx on public.students(teacher_id);
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$declare chosen_role public.user_role;begin chosen_role:=coalesce((new.raw_user_meta_data->>'role')::public.user_role,'teacher');insert into public.profiles(id,email,role) values(new.id,lower(new.email),chosen_role) on conflict(id)do update set email=excluded.email,updated_at=now();if chosen_role='teacher' then insert into public.teachers(profile_id)values(new.id)on conflict(profile_id)do nothing;end if;return new;end$$;
create trigger on_auth_user_created after insert or update of email on auth.users for each row execute function public.handle_new_user();
create function public.current_teacher_id() returns uuid language sql stable security definer set search_path=public as $$select id from teachers where profile_id=auth.uid()$$;
create function public.create_invitation(invite_email text,invite_expires_at timestamptz) returns public.invitations language plpgsql security definer set search_path=public as $$declare result public.invitations;begin if public.current_teacher_id() is null then raise exception 'Teacher access required';end if;insert into invitations(teacher_id,student_email,expires_at)values(public.current_teacher_id(),lower(invite_email),invite_expires_at)returning * into result;return result;end$$;
create function public.get_invitation_by_token(invite_token uuid) returns public.invitations language sql stable security definer set search_path=public as $$select * from invitations where token=invite_token and status='pending' and expires_at>now()$$;
create function public.accept_invitation(invite_token uuid) returns void language plpgsql security definer set search_path=public as $$declare inv invitations; prof profiles;begin select * into inv from invitations where token=invite_token for update;if inv.id is null or inv.status<>'pending' or inv.expires_at<=now() then raise exception 'Invitation unavailable';end if;select * into prof from profiles where id=auth.uid();if prof.id is null or lower(prof.email)<>lower(inv.student_email) then raise exception 'Invitation email mismatch';end if;if exists(select 1 from teachers where profile_id=auth.uid()) then raise exception 'Teacher accounts cannot accept student invitations';end if;update profiles set role='student',updated_at=now() where id=auth.uid();insert into students(profile_id,teacher_id)values(auth.uid(),inv.teacher_id)on conflict(profile_id)do update set teacher_id=excluded.teacher_id;update invitations set status='accepted' where id=inv.id;end$$;
grant execute on function public.create_invitation(text,timestamptz) to authenticated;grant execute on function public.get_invitation_by_token(uuid) to anon,authenticated;grant execute on function public.accept_invitation(uuid) to authenticated;
alter table profiles enable row level security;alter table teachers enable row level security;alter table students enable row level security;alter table invitations enable row level security;
create policy "profiles read related" on profiles for select to authenticated using(id=auth.uid() or id in(select profile_id from teachers where id=public.current_teacher_id()) or id in(select profile_id from students where teacher_id=public.current_teacher_id()) or id in(select t.profile_id from teachers t join students s on s.teacher_id=t.id where s.profile_id=auth.uid()));
create policy "teachers read related" on teachers for select to authenticated using(profile_id=auth.uid() or id in(select teacher_id from students where profile_id=auth.uid()));
create policy "teachers own students" on students for select to authenticated using(teacher_id=public.current_teacher_id() or profile_id=auth.uid());
create policy "teachers remove students" on students for delete to authenticated using(teacher_id=public.current_teacher_id());
create policy "teachers invitations select" on invitations for select to authenticated using(teacher_id=public.current_teacher_id());
create policy "teachers invitations update" on invitations for update to authenticated using(teacher_id=public.current_teacher_id()) with check(teacher_id=public.current_teacher_id());
